DROP TABLE IF EXISTS `voice_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voice_profiles` (
  `id` varchar(40) NOT NULL,
  `name` varchar(100) NOT NULL,
  `gender` varchar(10) NOT NULL,
  `languages` json DEFAULT NULL,
  `accent` varchar(100) DEFAULT NULL,
  `styles` json DEFAULT NULL,
  `latency_ms` int NOT NULL,
  `premium` tinyint(1) NOT NULL,
  `sample_text` text,
  `provider` varchar(100) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `locale` varchar(15) DEFAULT NULL,
  `description` text,
  `provider_voice_id` varchar(100) DEFAULT NULL,
  `speaking_rate` float NOT NULL DEFAULT '1',
  `pitch` float NOT NULL DEFAULT '1',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `model_codes` json DEFAULT NULL,
  `provider_settings` json DEFAULT NULL,
  `tenant_id` varchar(40) DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'platform',
  `clone_metadata` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_voice_profiles_provider` (`provider`),
  KEY `ix_voice_profiles_status` (`status`),
  KEY `ix_voice_profiles_sort_order` (`sort_order`),
  KEY `ix_voice_profiles_tenant_id` (`tenant_id`),
  CONSTRAINT `fk_voice_profiles_tenant_id` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
